#include <stdio.h>

struct student
{
    double midterm;
    double finalterm;
    double average;
};

int main(void)
{
    struct student s;

    if (scanf("%lf %lf", &s.midterm, &s.finalterm) != 2)
        return 1;

    s.average = (s.midterm + s.finalterm) / 2;
    printf("average=%.2f\n", s.average);

    return 0;
}

#include <stdio.h>

struct student
{
    int num;
    double midterm;
    double finalterm;
    double average;
};

/* 用指向结构体的指针读入一名学生并算平均分 */
void read_one(struct student *p)
{
    if (scanf("%d %lf %lf", &p->num, &p->midterm, &p->finalterm) != 3)
        p->num = -1;
    p->average = (p->midterm + p->finalterm) / 2;
}

int main(void)
{
    struct student s[3];
    struct student *p;
    int i;

    for (i = 0; i < 3; i++)
        read_one(&s[i]);

    for (p = s; p < s + 3; p++)
        printf("%d %.2f %.2f %.2f\n", p->num, p->midterm, p->finalterm, p->average);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

struct node
{
    int data;
    struct node *next;
};

int main(void)
{
    struct node *ph, *p, *tail;
    int x;

    /* 带头结点：ph->data 不放数据，表空的条件是 ph->next == NULL */
    ph = (struct node *)malloc(sizeof(struct node));
    if (ph == NULL)
        return 1;
    ph->next = NULL;
    tail = ph;

    while (scanf("%d", &x) == 1 && x != -1) {
        p = (struct node *)malloc(sizeof(struct node));
        if (p == NULL)
            return 1;
        p->data = x;
        p->next = NULL;
        tail->next = p;
        tail = p;
    }

    if (ph->next == NULL) {
        printf("NULL\n");
    }
    else {
        for (p = ph->next; p != NULL; p = p->next)
            printf("%d\n", p->data);
    }

    while (ph != NULL) {
        p = ph->next;
        free(ph);
        ph = p;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

struct node
{
    int info;
    struct node *next;
    struct node *pre;
};

/* 从头至尾输出双向链表 */
void printl(struct node *head)
{
    struct node *p = head;
    int first = 1;

    while (p != NULL) {
        if (!first)
            printf(" ");
        printf("%d", p->info);
        first = 0;
        p = p->next;
    }
    printf("\n");
}

int main(void)
{
    struct node *head = NULL, *tail = NULL, *p, *q;
    int n, i, x;

    if (scanf("%d", &n) != 1)
        return 1;
    if (n < 0 || n > 1000)
        return 1;

    for (i = 0; i < n; i++) {
        if (scanf("%d", &x) != 1)
            return 1;
        p = (struct node *)malloc(sizeof(struct node));
        if (p == NULL)
            return 1;
        p->info = x;
        p->next = NULL;
        p->pre = tail;
        if (tail == NULL)
            head = p;
        else
            tail->next = p;
        tail = p;
    }

    printl(head);

    p = head;
    while (p != NULL) {
        q = p->next;
        free(p);
        p = q;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

struct node
{
    char data;
    struct node *next;
};

/* 在值为 a 的结点前插入值为 key 的结点；若没有值为 a 的结点，则插在链表最后 */
void insert(struct node *head, char a, char key)
{
    struct node *p = head;
    struct node *s;

    while (p->next != NULL && p->next->data != a)
        p = p->next;

    s = (struct node *)malloc(sizeof(struct node));
    if (s == NULL)
        return;
    s->data = key;
    s->next = p->next;
    p->next = s;
}

int main(void)
{
    struct node *head, *tail, *p, *q;
    char ch, a, key;
    int first;

    head = (struct node *)malloc(sizeof(struct node));
    if (head == NULL)
        return 1;
    head->next = NULL;
    tail = head;

    /* 第一行：字符序列，以 $ 结束 */
    while (scanf("%c", &ch) == 1 && ch != '$') {
        if (ch == '\n' || ch == '\r' || ch == ' ' || ch == '\t')
            continue;
        p = (struct node *)malloc(sizeof(struct node));
        if (p == NULL)
            return 1;
        p->data = ch;
        p->next = NULL;
        tail->next = p;
        tail = p;
    }

    /* 第二行：a 与 key */
    if (scanf(" %c %c", &a, &key) != 2)
        return 1;
    insert(head, a, key);

    first = 1;
    for (p = head->next; p != NULL; p = p->next) {
        if (!first)
            printf(" ");
        printf("%c", p->data);
        first = 0;
    }
    printf("\n");

    p = head;
    while (p != NULL) {
        q = p->next;
        free(p);
        p = q;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

struct node
{
    char data;
    struct node *next;
};

/* 头结点位置不变，其后数据结点次序完全反转：逐个摘下再头插 */
void reverse_list(struct node *head)
{
    struct node *p = head->next;
    struct node *q;

    head->next = NULL;
    while (p != NULL) {
        q = p->next;
        p->next = head->next;
        head->next = p;
        p = q;
    }
}

int main(void)
{
    struct node *head, *tail, *p, *q;
    char ch;
    int first;

    head = (struct node *)malloc(sizeof(struct node));
    if (head == NULL)
        return 1;
    head->next = NULL;
    tail = head;

    while (scanf("%c", &ch) == 1 && ch != '$') {
        if (ch == '\n' || ch == '\r' || ch == ' ' || ch == '\t')
            continue;
        p = (struct node *)malloc(sizeof(struct node));
        if (p == NULL)
            return 1;
        p->data = ch;
        p->next = NULL;
        tail->next = p;
        tail = p;
    }

    reverse_list(head);

    first = 1;
    for (p = head->next; p != NULL; p = p->next) {
        if (!first)
            printf(" ");
        printf("%c", p->data);
        first = 0;
    }
    printf("\n");

    p = head;
    while (p != NULL) {
        q = p->next;
        free(p);
        p = q;
    }

    return 0;
}

#include <stdio.h>

/* 把 unsigned long 的低 16 位与高 16 位当作两个 unsigned int 输出 */
void partition(unsigned long n)
{
    unsigned int low, high;

    low = (unsigned int)(n & 0xFFFFUL);
    high = (unsigned int)((n >> 16) & 0xFFFFUL);
    printf("%u %u\n", low, high);
}

int main(void)
{
    unsigned long n;

    if (scanf("%lu", &n) != 1)
        return 1;
    partition(n);

    return 0;
}

